import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class BFSResult {
        int farthest;
        int[] distance;
        int[] parent;

        BFSResult(int farthest, int[] distance, int[] parent) {
            this.farthest = farthest;
            this.distance = distance;
            this.parent = parent;
        }
    }

    static BFSResult bfs(int start, ArrayList<Integer>[] graph) {
        int n = graph.length;
        int[] distance = new int[n];
        int[] parent = new int[n];
        Arrays.fill(distance, -1);

        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = start;
        distance[start] = 0;
        parent[start] = -1;
        int farthest = start;

        while (head < tail) {
            int u = queue[head++];
            if (distance[u] > distance[farthest]) farthest = u;

            for (int v : graph[u]) {
                if (distance[v] == -1) {
                    distance[v] = distance[u] + 1;
                    parent[v] = u;
                    queue[tail++] = v;
                }
            }
        }

        return new BFSResult(farthest, distance, parent);
    }

    static long countAtDepth(
            int start, int blocked, int target,
            ArrayList<Integer>[] graph,
            int[] nodeStack, int[] parentStack, int[] depthStack
    ) {
        int top = 0;
        nodeStack[top] = start;
        parentStack[top] = -1;
        depthStack[top++] = 0;

        long count = 0;
        while (top > 0) {
            --top;
            int u = nodeStack[top];
            int parent = parentStack[top];
            int depth = depthStack[top];

            if (depth == target) {
                count++;
                continue;
            }

            for (int v : graph[u]) {
                if (v != parent && v != blocked) {
                    nodeStack[top] = v;
                    parentStack[top] = u;
                    depthStack[top++] = depth + 1;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < n - 1; i++) {
            int x = fs.nextInt() - 1;
            int y = fs.nextInt() - 1;
            graph[x].add(y);
            graph[y].add(x);
        }

        int endpointA = bfs(0, graph).farthest;
        BFSResult fromA = bfs(endpointA, graph);
        int endpointB = fromA.farthest;
        int diameter = fromA.distance[endpointB];

        int[] path = new int[diameter + 1];
        int current = endpointB;
        for (int i = diameter; i >= 0; i--) {
            path[i] = current;
            current = fromA.parent[current];
        }

        int[] nodeStack = new int[n];
        int[] parentStack = new int[n];
        int[] depthStack = new int[n];
        long ways;

        if (diameter % 2 == 0) {
            int center = path[diameter / 2];
            int radius = diameter / 2;
            long total = 0;
            long sumSquares = 0;

            for (int neighbor : graph[center]) {
                long count = countAtDepth(
                        neighbor, -1, radius - 1, graph,
                        nodeStack, parentStack, depthStack
                );
                total += count;
                sumSquares += count * count;
            }

            ways = (total * total - sumSquares) / 2;
        } else {
            int center1 = path[diameter / 2];
            int center2 = path[diameter / 2 + 1];
            int radius = diameter / 2;

            long left = countAtDepth(
                    center1, center2, radius, graph,
                    nodeStack, parentStack, depthStack
            );
            long right = countAtDepth(
                    center2, center1, radius, graph,
                    nodeStack, parentStack, depthStack
            );
            ways = left * right;
        }

        System.out.println(diameter + 1);
        System.out.println(ways);
    }
}
